// verify-demo.mjs — real-browser verification of demo.html (load + resize + RO lifecycle)
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const REPO = 'D:/dev/ab-tasks/chessground-qwen-r1';
const PORT = 8123;
const CDP_PORT = 9333;

// --- static server for the repo root
const { createServer } = await import('node:http');
const { readFile } = await import('node:fs/promises');
const mime = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.map': 'application/json' };
const server = createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  const file = path.join(REPO, path.normalize(url.pathname).replace(/^([/\\])+/, ''));
  readFile(file).then(
    buf => {
      res.writeHead(200, { 'content-type': mime[path.extname(file)] || 'application/octet-stream' });
      res.end(buf);
    },
    () => { res.writeHead(404); res.end('not found'); },
  );
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

// --- launch headless chrome
const userDataDir = mkdtempSync(path.join(tmpdir(), 'cg-chrome-'));
const chrome = spawn(CHROME, [
  '--headless',
  `--remote-debugging-port=${CDP_PORT}`,
  `--user-data-dir=${userDataDir}`,
  '--no-first-run',
  '--no-default-browser-check',
  '--disable-gpu',
  'about:blank',
], { stdio: 'ignore' });

