await send('Page.addScriptToEvaluateOnNewDocument', { source: RO_HOOK });
await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });

// wait for load
for (let i = 0; i < 100 && !events.some(e => e.method === 'Page.loadEventFired'); i++)
  await new Promise(r => setTimeout(r, 100));

const evaluate = (expression, awaitPromise = true) =>
  send('Runtime.evaluate', { expression, awaitPromise, returnByValue: true });

await new Promise(r => setTimeout(r, 300)); // let module script settle

const probe = (async () => {
