  cg.redrawAll();
  cg.redrawAll();
  out.roAfterRedraws = window.__ro.instances.length;
  out.liveAfterRedraws = window.__ro.instances.filter(o => !o.__disconnected).length;
  cg.destroy();
  out.liveAfterDestroy = window.__ro.instances.filter(o => !o.__disconnected).length;
  return out;
})()`;

const r = await send('Runtime.evaluate', { expression: PROBE, awaitPromise: true, returnByValue: true });
if (r.error || r.result.exceptionDetails)
  throw new Error(`probe failed: ${JSON.stringify(r.error ?? r.result.exceptionDetails)}`);

console.log(JSON.stringify(r.result.value, null, 2));
const pageErrors = events.filter(e => e.method === 'Runtime.exceptionThrown');
const consoleErrors = events.filter(e => e.method === 'Runtime.consoleAPICalled' && e.params.type === 'error');
console.log(`page exceptions: ${pageErrors.length}, console errors: ${consoleErrors.length}`);
for (const e of [...pageErrors, ...consoleErrors]) console.log(JSON.stringify(e.params.exceptionDetails ?? e.params.args));

ws.close();
chrome.kill();
server.close();

const o = r.result.value;
const expected = {
  boards: 5,
  roOnLoad: 5,
  widthBefore: '500px',
  widthAfter: '400px',
  roAfterNewBoard: 6,
  roAfterRedraws: 8,
  liveAfterRedraws: 6,
  liveAfterDestroy: 5,
};
const bad = Object.entries(expected).filter(([k, v]) => o[k] !== v);
if (bad.length || pageErrors.length || consoleErrors.length) {
  console.error(`FAIL: ${JSON.stringify(bad)}`);
  process.exit(1);
}
console.log('PASS: demo loads, board resizes via ResizeObserver, no RO duplication on redraw, RO disconnected on destroy');
